// ALU (Arithmetic Logic Unit)
// The ALU computes one of the following functions:
// x+y, x-y, y-x, 0, 1, -1, x, y, -x, -y, !x, !y,
// x+1, y+1, x-1, y-1, x&y, x|y
// based on 6 input bits (zx,nx,zy,ny,f,no)
// In addition, it computes two 1-bit outputs:
// if out==0, zr=1; else zr=0
// if out<0, ng=1; else ng=0

CHIP ALU {
    IN
        x[16], y[16],
        zx, nx, zy, ny, f, no;
    OUT
        out[16],
        zr, ng;

    PARTS:
    Mux16(a=x, b=false, sel=zx, out=xZeroed);
    Not16(in=xZeroed, out=xInverted);
    Mux16(a=xZeroed, b=xInverted, sel=nx, out=xProcessed);

    Mux16(a=y, b=false, sel=zy, out=yZeroed);
    Not16(in=yZeroed, out=yInverted);
    Mux16(a=yZeroed, b=yInverted, sel=ny, out=yProcessed);

    And16(a=xProcessed, b=yProcessed, out=andOut);
    Add16(a=xProcessed, b=yProcessed, out=addOut);
    Mux16(a=andOut, b=addOut, sel=f, out=aluOut);

    Not16(in=aluOut, out=aluOutInverted);
    Mux16(a=aluOut, b=aluOutInverted, sel=no, out=out, out[15]=ng);

    Or8Way(in=out[0..7], out=lowerSet);
    Or8Way(in=out[8..15], out=upperSet);
    Or(a=lowerSet, b=upperSet, out=anySet);
    Not(in=anySet, out=zr);
}
