@color
M=-1

(FILL)
@SCREEN
D=A
@address
M=D

(DRAW)
@address
D=M
@KBD
D=A-D
@POLL
D;JEQ

@color
D=M
@address
A=M
M=D
@address
M=M+1
@DRAW
0;JMP
